package com.plantgrowth.forecasting.controller;import com.plantgrowth.forecasting.dto.Contracts.*;import com.plantgrowth.forecasting.entity.*;import com.plantgrowth.forecasting.repository.UserRepository;import com.plantgrowth.forecasting.security.JwtService;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {final UserRepository users;final PasswordEncoder encoder;final JwtService jwt;final String guestEmail;AuthController(UserRepository u,PasswordEncoder e,JwtService j,@Value("${app.guest-email:guest@verdant.local}") String guestEmail){users=u;encoder=e;jwt=j;this.guestEmail=guestEmail.toLowerCase();}private Auth issue(User u){return new Auth(jwt.issue(u.getId(),u.getEmail(),u.getRole().name()),new UserView(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name()));}@PostMapping("/register") ResponseEntity<UserView> register(@Valid @RequestBody Register x){if(users.findByEmail(x.email().toLowerCase()).isPresent())throw new IllegalArgumentException("Email already registered");User u=new User();u.setFullName(x.fullName());u.setEmail(x.email());u.setPasswordHash(encoder.encode(x.password()));u=users.save(u);return ResponseEntity.status(201).body(new UserView(u.getId(),u.getFullName(),u.getEmail(),u.getRole().name()));}@PostMapping("/login") Auth login(@Valid @RequestBody Login x){User u=users.findByEmail(x.email().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!u.isActive()||!encoder.matches(x.password(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid email or password");return issue(u);}@PostMapping("/guest") Auth guest(){return new Auth(jwt.issue(0L,guestEmail,"GUEST"),new UserView(0L,"Guest explorer",guestEmail,"GUEST"));}}
